// Fission products, chapter 4 "TRISO layer migration and particle failure"
// (lessons 29-38): the widgets. Each registers with Lesson.widget(id, make)
// and runs on the page that has its element.
// Data: barrier-data.js and failure-data.js (generated by
// crates/dhoby-ghaut/examples/lesson_barriers from boon-lay's own calls),
// barrier-recorded.js (cited / pending). Models: barrier-physics.js; the
// layered walks of lesson 32 run in barrier-worker.js (no-lag rule).
(function () {
  "use strict";
  var L = window.Lesson, css = L.css, el = L.el;
  var BD = function () { return window.BARRIER_DATA; };
  var FD = function () { return window.FAILURE_DATA; };
  var BR = function () { return window.BARRIER_RECORDED; };
  var BP = function () { return window.BarrierPhysics; };
  var LAYER_COL = { kernel: "#c0392b", buffer: "#b0a184", IPyC: "#555c66", PyC: "#555c66", SiC: "#2a9d55", OPyC: "#3d4450", graphite: "#7a4cc2" };
  var EL_COL = { Cs: "#7a4cc2", Sr: "#2a9d55", Ag: "#7f8c8d", Kr: "#2f7fd8" };
  var YEAR = 3.15576e7;

  // ─── Helpers ──────────────────────────────────────────────────────────
  function fmtT(s) {
    if (!isFinite(s)) return "—";
    var u = [[1e6 * YEAR, "My"], [1e3 * YEAR, "ky"], [YEAR, "y"], [86400, "d"], [3600, "h"], [60, "min"], [1, "s"]];
    for (var i = 0; i < u.length; i++) if (s >= u[i][0]) return (s / u[i][0]).toPrecision(3) + " " + u[i][1];
    return s.toPrecision(3) + " s";
  }
  function sci(x, p) { return x === 0 ? "0" : (Math.abs(x) >= 1e-3 && Math.abs(x) < 1e4 ? x.toPrecision(p || 3) : x.toExponential((p || 3) - 1)); }
  function wrap(ctx, text, x, y, maxW, lh) {
    var words = String(text).split(" "), line = "";
    words.forEach(function (wd) {
      var t = line ? line + " " + wd : wd;
      if (ctx.measureText(t).width > maxW && line) { ctx.fillText(line, x, y); y += lh; line = wd; } else line = t;
    });
    if (line) { ctx.fillText(line, x, y); y += lh; }
    return y;
  }
  // A plot box: { x0, y0, x1, y1, lx: [lo, hi] (log10 if logx), ly: [...] }.
  function Box(x0, y0, x1, y1, xr, yr, logx, logy) {
    this.x0 = x0; this.y0 = y0; this.x1 = x1; this.y1 = y1; this.xr = xr; this.yr = yr; this.logx = logx; this.logy = logy;
  }
  Box.prototype.X = function (v) { var a = this.logx ? Math.log10(Math.max(v, 1e-300)) : v; return this.x0 + (a - this.xr[0]) / (this.xr[1] - this.xr[0]) * (this.x1 - this.x0); };
  Box.prototype.Y = function (v) { var a = this.logy ? Math.log10(Math.max(v, 1e-300)) : v; return this.y1 - (a - this.yr[0]) / (this.yr[1] - this.yr[0]) * (this.y1 - this.y0); };
  Box.prototype.frame = function (ctx, xlab, ylab, xt, yt) {
    var mut = css("--muted", "#5b636b"), self = this;
    ctx.strokeStyle = mut; ctx.lineWidth = 1; ctx.strokeRect(this.x0, this.y0, this.x1 - this.x0, this.y1 - this.y0);
    ctx.fillStyle = mut; ctx.font = "10px system-ui, sans-serif";
    (xt || []).forEach(function (t) { var x = self.X(t[0]); if (x < self.x0 - 1 || x > self.x1 + 1) return; ctx.fillText(t[1], x - ctx.measureText(t[1]).width / 2, self.y1 + 12); ctx.beginPath(); ctx.moveTo(x, self.y1); ctx.lineTo(x, self.y1 - 4); ctx.stroke(); });
    (yt || []).forEach(function (t) { var y = self.Y(t[0]); if (y < self.y0 - 1 || y > self.y1 + 1) return; ctx.fillText(t[1], self.x0 - 4 - ctx.measureText(t[1]).width, y + 3); ctx.beginPath(); ctx.moveTo(self.x0, y); ctx.lineTo(self.x0 + 4, y); ctx.stroke(); });
    ctx.font = "11px system-ui, sans-serif";
    if (xlab) ctx.fillText(xlab, (this.x0 + this.x1) / 2 - ctx.measureText(xlab).width / 2, this.y1 + 25);
    if (ylab) { ctx.save(); ctx.translate(this.x0 - 34, (this.y0 + this.y1) / 2); ctx.rotate(-Math.PI / 2); ctx.fillText(ylab, -ctx.measureText(ylab).width / 2, 0); ctx.restore(); }
  };
  Box.prototype.line = function (ctx, xs, ys, col, w, dash) {
    var self = this, started = false;
    ctx.strokeStyle = col; ctx.lineWidth = w || 2; ctx.setLineDash(dash || []);
    ctx.beginPath();
    xs.forEach(function (x, i) {
      var y = ys[i];
      if (y === null || y === undefined || !isFinite(y) || (self.logy && y <= 0)) { started = false; return; }
      var px = self.X(x), py = Math.max(self.y0, Math.min(self.y1, self.Y(y)));
      if (started) ctx.lineTo(px, py); else { ctx.moveTo(px, py); started = true; }
    });
    ctx.stroke(); ctx.setLineDash([]);
  };
  function decTicks(lo, hi, every) { var t = []; for (var e = Math.ceil(lo); e <= hi; e += (every || 1)) t.push([Math.pow(10, e), "1e" + e]); return t; }
  function linTicks(lo, hi, step, fmt) { var t = []; for (var v = Math.ceil(lo / step) * step; v <= hi + 1e-9; v += step) t.push([v, fmt ? fmt(v) : String(v)]); return t; }
  function legend(ctx, items, x, y, w) {
    ctx.font = "11px system-ui, sans-serif";
    var cx = x, cy = y;
    items.forEach(function (it) {
      var tw = ctx.measureText(it[0]).width + 26;
      if (cx + tw > x + w) { cx = x; cy += 15; }
      ctx.strokeStyle = it[1]; ctx.lineWidth = 2; ctx.setLineDash(it[2] || []);
      ctx.beginPath(); ctx.moveTo(cx, cy - 4); ctx.lineTo(cx + 18, cy - 4); ctx.stroke(); ctx.setLineDash([]);
      ctx.fillStyle = css("--fg", "#1d2125"); ctx.fillText(it[0], cx + 22, cy); cx += tw + 6;
    });
    return cy + 15;
  }
  // A walker D row from the data (null if a gap).
  function walkerRow(elm, layer) { return BD().walker.filter(function (w) { return w.el === elm && w.layer === layer; })[0]; }
  function wD(elm, layer, tC) { var w = walkerRow(elm, layer); return w && w.d ? BP().dAt(tC, BD().tC, w.d) : null; }
  // The five-layer D list for a walk (IPyC and OPyC are the walker's PyC).
  function layerD(elm, tC) { return [wD(elm, "kernel", tC), wD(elm, "buffer", tC), wD(elm, "PyC", tC), wD(elm, "SiC", tC), wD(elm, "PyC", tC)]; }
  function residence() { return FD().strength.residenceDays * 86400; }
  var worker = null, wid = 0, handlers = {};
  function ask(msg, cb) {
    if (!worker) { worker = new Worker("barrier-worker.js"); worker.onmessage = function (e) { var h = handlers[e.data.id]; if (h) h(e.data); }; }
    msg.id = ++wid; handlers[msg.id] = cb; worker.postMessage(msg); return msg.id;
  }

  // ─── 29: the particle, bare to TRISO ──────────────────────────────────
  function particle(root) {
    var st = { mode: "triso", pick: null };
    var JOBS = { buffer: "buffer", IPyC: "ipyc", SiC: "sic", OPyC: "opyc" };
    function layersFor(mode) {
      var r = BD().radii, um = function (x) { return x * 1e6; };
      if (mode === "bare") return [["kernel", um(r[0])]];
      // BISO: buffer + one dense PyC (Fang 2021 p. 2). Thicknesses are
      // ILLUSTRATIVE: the HTR-10 buffer, and a PyC as thick as HTR-10's
      // IPyC + SiC + OPyC together (no BISO dimensions in the workspace).
      if (mode === "biso") return [["kernel", um(r[0])], ["buffer", um(r[1])], ["PyC", um(r[4])]];
      return [["kernel", um(r[0])], ["buffer", um(r[1])], ["IPyC", um(r[2])], ["SiC", um(r[3])], ["OPyC", um(r[4])]];
    }
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var ls = layersFor(st.mode), top = 50, wide = w >= 560, pw = wide ? w * 0.6 : w, ph = wide ? h - top - 8 : (h - top) * 0.56;
        var cx = pw / 2, cy = top + ph / 2, R = ls[ls.length - 1][1], sc = 0.46 * Math.min(pw, ph) / R * zoom;
        for (var i = ls.length - 1; i >= 0; i--) {
          ctx.fillStyle = LAYER_COL[ls[i][0]]; ctx.globalAlpha = st.pick && st.pick !== ls[i][0] ? 0.35 : 0.9;
          ctx.beginPath(); ctx.arc(cx, cy, ls[i][1] * sc, 0, 2 * Math.PI); ctx.fill();
        }
        ctx.globalAlpha = 1;
        // Labels along a ray (wide), or a row of swatches (narrow).
        ctx.font = "11px system-ui, sans-serif"; ctx.fillStyle = css("--fg", "#1d2125");
        if (!wide) {
          var lx0 = 8, ly0 = top + ph + 10;
          ls.forEach(function (l) {
            var tw = ctx.measureText(l[0]).width;
            ctx.fillStyle = LAYER_COL[l[0]]; ctx.fillRect(lx0, ly0 - 8, 10, 10);
            ctx.fillStyle = css("--fg", "#1d2125"); ctx.fillText(l[0], lx0 + 13, ly0 + 1); lx0 += tw + 22;
          });
        }
        if (wide) ls.forEach(function (l, k) {
          var r0 = k ? ls[k - 1][1] : 0, rm = (r0 + l[1]) / 2 * sc, a = -0.6 - 0.28 * k;
          var x = cx + rm * Math.cos(a), y = cy + rm * Math.sin(a);
          ctx.beginPath(); ctx.arc(x, y, 2, 0, 2 * Math.PI); ctx.fill();
          var lx = cx + (R * sc + 8) * Math.cos(a);
          ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(lx, cy + (R * sc + 8) * Math.sin(a)); ctx.strokeStyle = css("--muted", "#5b636b"); ctx.lineWidth = 1; ctx.stroke();
          ctx.fillText(l[0] + (k ? " " + (l[1] - r0).toFixed(0) + " µm" : " r " + l[1].toFixed(0) + " µm"), Math.min(lx + 2, pw - 100), cy + (R * sc + 8) * Math.sin(a) - 2);
        });
        // The iodine levels (Kugeler p. 42).
        var rows = BR().iodine.rows, bx0 = wide ? pw + 16 : 50, by0 = wide ? top + 30 : top + ph + 26, bw = wide ? w - pw - 30 : w - 66, bh = wide ? h - top - 70 : h - by0 - 30;
        var B = new Box(bx0, by0, bx0 + bw, by0 + bh, [0, 3], [-10, 0], false, true);
        B.frame(ctx, "", "131I released", [], decTicks(-10, 0, 2));
        var which = { bare: 0, biso: 1, triso: 2 }[st.mode];
        rows.forEach(function (row, k) {
          var x = B.X(k + 0.15), xw = B.X(k + 0.85) - x, ylo = B.Y(row.hi), yhi = B.Y(row.lo);
          ctx.fillStyle = k === which ? "#b85c38" : "#c9ced3";
          ctx.fillRect(x, ylo, xw, Math.max(3, B.y1 - ylo));
          ctx.fillStyle = css("--fg", "#1d2125"); ctx.font = "10px system-ui, sans-serif";
          ctx.fillText(["bare", "BISO-contam.", "TRISO"][k], x, B.y1 + 12);
          if (yhi > ylo + 2) { ctx.strokeStyle = "#b85c38"; ctx.strokeRect(x, ylo, xw, yhi - ylo); }
        });
        var msg = { bare: "A bare UO2 kernel: nothing between the fission products and the coolant but the kernel itself.", biso: "BISO: a porous buffer and one dense pyrocarbon shell (layer thicknesses here ILLUSTRATIVE).", triso: "TRISO (HTR-10 radii, TrisoSpec::HTR10_LI2014): buffer, inner PyC, SiC, outer PyC." }[st.mode];
        if (st.pick && JOBS[st.pick]) msg = st.pick + " (Kugeler 2017, Table 5, pp. 32-33): " + BR().layerJobs[JOBS[st.pick]].join(" ");
        else if (st.pick === "kernel") msg = "Kernel: makes almost all the fission products; holds many of them as oxides (Kugeler 2017, p. 32).";
        return msg + " Bars: 131I released in 1600 °C heating tests, as Kugeler 2017 p. 42 reports them.";
      },
      panel: function (body, redraw) {
        L.buttons(body, "Particle", [["bare", "Bare kernel"], ["biso", "BISO"], ["triso", "TRISO"]], st.mode, function (v) { st.mode = v; st.pick = null; redraw(); });
        L.buttons(body, "What does this layer do?", [["kernel", "Kernel"], ["buffer", "Buffer"], ["IPyC", "IPyC"], ["SiC", "SiC"], ["OPyC", "OPyC"]], null, function (v) { st.pick = v; if (v !== "kernel" && v !== "buffer") st.mode = "triso"; redraw(); });
        body.append(el("p", { "class": "w-note" }, "BISO layer thicknesses are ILLUSTRATIVE (no BISO dimensions in the workspace). The middle bar is TRISO fuel contaminated by older BISO fuel in the AVR, not BISO fuel itself (Kugeler p. 42)."));
      }
    });
    return frame;
  }

  // ─── 30: D in each layer, and the time to cross it ────────────────────
  function dlayers(root) {
    var st = { el: "Cs", tC: 1200 };
    var frame = new L.Frame(root, {
      reset: function () { st.tC = 1200; }, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var D = BD(), th = D.thickness, wide = w >= 600, top = 52;
        var A = wide ? new Box(56, top, w * 0.5 - 10, h - 40, [600, 1800], [-24, -6], false, true)
                     : new Box(56, top, w - 12, top + (h - top) * 0.48, [600, 1800], [-24, -6], false, true);
        A.frame(ctx, wide ? "temperature (°C)" : "", "D (m²/s)", linTicks(600, 1800, 300), decTicks(-24, -6, 3));
        var leg = [];
        ["kernel", "buffer", "PyC", "SiC"].forEach(function (ly) {
          var row = walkerRow(st.el, ly);
          if (row && row.d) { A.line(ctx, D.tC, row.d, LAYER_COL[ly], 2); leg.push([ly, LAYER_COL[ly]]); }
        });
        var g = D.atops.filter(function (a) { return a.el === st.el && a.layer === "graphite"; })[0];
        A.line(ctx, D.tC, g.d, LAYER_COL.graphite, 2, [5, 4]); leg.push(["graphite (ATOPS)", LAYER_COL.graphite, [5, 4]]);
        if (st.el === "Ag") { var s = D.atops.filter(function (a) { return a.layer === "SiC"; })[0]; A.line(ctx, D.tC, s.d, LAYER_COL.SiC, 2, [2, 3]); leg.push(["SiC-Ag (ATOPS)", LAYER_COL.SiC, [2, 3]]); }
        ctx.strokeStyle = "#b85c38"; ctx.beginPath(); ctx.moveTo(A.X(st.tC), A.y0); ctx.lineTo(A.X(st.tC), A.y1); ctx.stroke();
        legend(ctx, leg, A.x0 + 4, A.y0 + 14, A.x1 - A.x0 - 8);
        // Crossing times l^2/D at the slider temperature.
        var B = wide ? new Box(w * 0.5 + 60, top, w - 12, h - 40, [-0.5, 4.5], [0, 14 + Math.log10(zoom) * 0], false, true)
                     : new Box(56, top + (h - top) * 0.48 + 34, w - 12, h - 28, [-0.5, 4.5], [0, 14], false, true);
        B.frame(ctx, "", "time to cross, l²/D (s)", [], decTicks(0, 14, 2));
        var names = [["kernel", "kernel", th.kernel], ["buffer", "buffer", th.buffer], ["IPyC", "PyC", th.IPyC], ["SiC", "SiC", th.SiC], ["OPyC", "PyC", th.OPyC]];
        var gaps = [];
        names.forEach(function (n, k) {
          var d = wD(st.el, n[1], st.tC), x = B.X(k - 0.35), xw = B.X(k + 0.35) - x;
          ctx.fillStyle = css("--fg", "#1d2125"); ctx.font = "10px system-ui, sans-serif"; ctx.fillText(n[0], x, B.y1 + 12);
          if (d === null) { ctx.strokeStyle = "#999"; ctx.setLineDash([3, 3]); ctx.strokeRect(x, B.y0 + 4, xw, B.y1 - B.y0 - 8); ctx.setLineDash([]); ctx.fillText("?", x + xw / 2 - 3, (B.y0 + B.y1) / 2); gaps.push(n[0]); return; }
          var tc = n[2] * n[2] / d, y = B.Y(tc);
          ctx.fillStyle = LAYER_COL[n[0]]; ctx.fillRect(x, Math.max(B.y0, y), xw, B.y1 - Math.max(B.y0, y));
        });
        [[YEAR, "1 year", true], [residence(), "HTR-10 residence", false]].forEach(function (r) { var y = B.Y(r[0]); ctx.strokeStyle = "#b85c38"; ctx.setLineDash([4, 3]); ctx.beginPath(); ctx.moveTo(B.x0, y); ctx.lineTo(B.x1, y); ctx.stroke(); ctx.setLineDash([]); ctx.fillStyle = "#b85c38"; ctx.fillText(r[1], r[2] ? B.x0 + 3 : B.x1 - ctx.measureText(r[1]).width - 2, r[2] ? y + 11 : y - 3); });
        var sic = wD(st.el, "SiC", st.tC), pyc = wD(st.el, "PyC", st.tC);
        var s = st.el + " at " + st.tC + " °C: SiC takes " + fmtT(th.SiC * th.SiC / sic) + " to cross, the IPyC " + fmtT(th.IPyC * th.IPyC / pyc) + ".";
        if (gaps.length) s += " No coefficient in the " + gaps.join(", ") + ": boon-lay's walker has a todo!() there (gh:#541), so no number is shown.";
        return s;
      },
      panel: function (body, redraw) {
        L.buttons(body, "Element", [["Cs", "Cs"], ["Sr", "Sr"], ["Ag", "Ag"], ["Kr", "Kr"]], st.el, function (v) { st.el = v; redraw(); });
        L.slider(body, "Temperature (°C)", 600, 1800, 50, st.tC, function (v) { st.tC = v; redraw(); return v + " °C"; });
        body.append(el("p", { "class": "w-note" }, "Solid lines: boon-lay's random-walk coefficients (Jiang et al. 2023). Dashed: TRISO-ATOPS's graphite (and, for Ag, SiC) correlations. Every other element is walked as silver (gh:#541)."));
      }
    });
    return frame;
  }

  // ─── 31: which layer holds which family ───────────────────────────────
  function matrix(root) {
    var st = { tC: 1200 };
    // Families with walker data, and two with only a cited statement.
    var FAM = [["Kr", "noble gas (Kr)"], ["I", "iodine"], ["Cs", "Cs"], ["Sr", "Sr"], ["Ag", "Ag"], ["Pd", "Pd"]];
    var LAY = [["buffer", "buffer"], ["IPyC", "PyC"], ["SiC", "SiC"], ["OPyC", "PyC"]];
    function cell(fam, lay, tC) {
      var th = BD().thickness[lay[0]];
      if (fam === "Kr" || fam === "Cs" || fam === "Sr" || fam === "Ag") {
        var d = wD(fam, lay[1], tC);
        if (d === null) return { v: "?", why: "no coefficient (todo!, gh:#541)" };
        var ratio = th * th / d / residence();
        return { v: ratio > 10 ? "holds" : ratio > 0.1 ? "partly" : "leaks", why: "l²/D = " + fmtT(th * th / d) + " (data)" };
      }
      // Kugeler Table 5, p. 33: SiC retains all gaseous and solid fission
      // products except Ag, below 1250 °C in operation and to 1600 °C in accidents.
      if (lay[0] === "SiC" && tC <= 1600) return { v: "holds", why: "cited: Kugeler 2017 Table 5, p. 33" };
      return { v: "?", why: "source pending" };
    }
    var COL = { holds: "#2a9d55", partly: "#d4a017", leaks: "#c0392b", "?": "#c9ced3" };
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var top = 70, x0 = 64, cw = (w - x0 - 10) / FAM.length, ch = Math.min(56, (h - top - 50) / LAY.length) * Math.min(zoom, 1.4);
        ctx.font = "11px system-ui, sans-serif"; ctx.fillStyle = css("--fg", "#1d2125");
        FAM.forEach(function (f, j) { wrap(ctx, f[1], x0 + j * cw + 3, top - 20, cw - 4, 11); });
        var uncovered = [];
        FAM.forEach(function (f, j) {
          var any = false;
          LAY.forEach(function (l, i) {
            var c = cell(f[0], l, st.tC), x = x0 + j * cw, y = top + i * ch;
            if (c.v === "holds") any = true;
            ctx.fillStyle = COL[c.v]; ctx.fillRect(x + 2, y + 2, cw - 4, ch - 4);
            ctx.fillStyle = c.v === "?" ? "#333" : "#fff"; ctx.font = "bold 11px system-ui, sans-serif"; ctx.fillText(c.v, x + 6, y + 18);
          });
          if (!any) uncovered.push(f[1]);
        });
        ctx.font = "11px system-ui, sans-serif"; ctx.fillStyle = css("--fg", "#1d2125");
        LAY.forEach(function (l, i) { ctx.fillText(l[0], 6, top + i * ch + ch / 2 + 4); });
        var y = top + LAY.length * ch + 16;
        ctx.fillStyle = css("--muted", "#5b636b");
        wrap(ctx, "holds: the layer alone takes more than 10 × HTR-10's residence (" + fmtT(residence()) + ") to cross; partly: 0.1 to 10 ×; leaks: less. ? = no data and no citation.", 8, y, w - 16, 13);
        return "At " + st.tC + " °C, not held by any one layer: " + (uncovered.length ? uncovered.join(", ") : "none") + ". Every column is covered by at least one layer only if that list is empty; no row holds everything.";
      },
      panel: function (body, redraw) {
        L.slider(body, "Temperature (°C)", 600, 1800, 50, st.tC, function (v) { st.tC = v; redraw(); return v + " °C"; });
        body.append(el("p", { "class": "w-note" }, "Kr, Cs, Sr, Ag: boon-lay's coefficients and the HTR-10 thicknesses. Iodine and Pd: only Kugeler's Table 5 statement for SiC; the rest is source pending. A rule of thumb (10 × the residence), not a release calculation: lesson 32 does that."));
      }
    });
    return frame;
  }

  // ─── 32: across the whole particle (worker) ───────────────────────────
  function whole(root) {
    var st = { el: "Cs", tC: 1600, tracks: null, sweep: {}, running: false, jobId: 0, k: 0 };
    var TEMPS = [1000, 1100, 1200, 1300, 1400, 1500, 1600, 1700, 1800];
    function runTracks(redraw) {
      st.tracks = null;
      ask({ cmd: "tracks", radii: BD().radii, D: layerD(st.el, st.tC), k: 5, seed: 32 + st.tC, maxHops: 3e6 }, function (m) { st.tracks = m; redraw(); });
    }
    function runSweep(redraw) {
      if (st.jobId) worker.postMessage({ cmd: "stop" });
      var key = st.el; st.sweep[key] = []; st.running = true;
      st.jobId = ask({ cmd: "sweep", radii: BD().radii, temps: TEMPS, D: TEMPS.map(function (t) { return layerD(st.el, t); }), n: 80, seed: 3200, maxHops: 2e7 }, function (m) {
        if (m.cmd === "point") st.sweep[key].push(m);
        if (m.cmd === "done") { st.running = false; st.jobId = 0; }
        redraw();
      });
      redraw();
    }
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false },
      onSeen: function () {},
      draw: function (ctx, w, h, zoom) {
        var D = BD(), r = D.radii.map(function (x) { return x * 1e6; }), wide = w >= 600, top = 52;
        // Left/top: radius against log time for a few atoms.
        var A = wide ? new Box(56, top, w * 0.5 - 8, h - 40, [0, 13], [0, r[4]], true, false)
                     : new Box(56, top, w - 12, top + (h - top) * 0.46, [0, 13], [0, r[4]], true, false);
        A.xr = [A.xr[0] + (zoom - 1) * 1.5, A.xr[1]];
        r.forEach(function (rr, k) { var y0 = A.Y(k ? r[k - 1] : 0), y1 = A.Y(rr); ctx.fillStyle = LAYER_COL[["kernel", "buffer", "IPyC", "SiC", "OPyC"][k]]; ctx.globalAlpha = 0.18; ctx.fillRect(A.x0, y1, A.x1 - A.x0, y0 - y1); ctx.globalAlpha = 1; });
        A.frame(ctx, wide ? "time (s, log)" : "", "radius (µm)", decTicks(A.xr[0], 13, 2), linTicks(0, r[4], 100));
        if (st.tracks) st.tracks.tracks.forEach(function (tr, k) {
          A.line(ctx, tr.map(function (p) { return Math.max(p[0], 1); }), tr.map(function (p) { return p[1] * 1e6; }), ["#7a4cc2", "#2a9d55", "#b85c38", "#2f7fd8", "#333"][k % 5], 1.2);
        });
        // Right/bottom: mean time to get out against temperature.
        var B = wide ? new Box(w * 0.5 + 56, top, w - 12, h - 40, [1000, 1800], [4, 16], false, true)
                     : new Box(56, top + (h - top) * 0.46 + 34, w - 12, h - 28, [1000, 1800], [4, 16], false, true);
        B.frame(ctx, "temperature (°C)", "mean time out (s)", linTicks(1000, 1800, 200), decTicks(4, 16, 2));
        var xs = [], ex = [];
        for (var t = 1000; t <= 1800; t += 25) { xs.push(t); ex.push(BP().exactMean(D.radii, layerD(st.el, t))); }
        B.line(ctx, xs, ex, "#111", 1.5);
        var pts = st.sweep[st.el] || [];
        pts.forEach(function (p) {
          if (!p.mean) return;
          var x = B.X(p.tC); ctx.strokeStyle = EL_COL[st.el]; ctx.lineWidth = 1.5;
          ctx.beginPath(); ctx.moveTo(x, B.Y(p.mean + 2 * p.se)); ctx.lineTo(x, B.Y(Math.max(p.mean - 2 * p.se, p.mean / 10))); ctx.stroke();
          ctx.fillStyle = EL_COL[st.el]; ctx.beginPath(); ctx.arc(x, B.Y(p.mean), 3.5, 0, 2 * Math.PI); ctx.fill();
        });
        var hl = D.halfLife[st.el]; ctx.strokeStyle = "#b85c38"; ctx.setLineDash([4, 3]); var yh = B.Y(hl);
        ctx.beginPath(); ctx.moveTo(B.x0, yh); ctx.lineTo(B.x1, yh); ctx.stroke(); ctx.setLineDash([]);
        ctx.fillStyle = "#b85c38"; ctx.font = "10px system-ui, sans-serif"; ctx.fillText("half-life", B.x1 - 46, yh - 3);
        legend(ctx, [["exact mean (diffusion equation)", "#111"], ["layered walk, ±2 s.e.", EL_COL[st.el]]], B.x0 + 4, B.y0 + 12, B.x1 - B.x0 - 8);
        var s = st.el + ": " + (st.tracks ? st.tracks.out.filter(Boolean).length + " of 5 atoms left the particle (traces at " + st.tC + " °C)" : "walking 5 atoms…");
        s += st.running ? "; sweep running in the background (" + pts.length + " of " + TEMPS.length + ")." : ".";
        return s + " No decay here: where the curve is above the half-life line, most atoms would decay before they got out.";
      },
      panel: function (body, redraw) {
        L.buttons(body, "Element", [["Cs", "Cs-137"], ["Ag", "Ag-110m"], ["Sr", "Sr-90"]], st.el, function (v) { st.el = v; runTracks(redraw); if (!st.sweep[v]) runSweep(redraw); redraw(); });
        L.slider(body, "Temperature of the traces (°C)", 1000, 1800, 100, st.tC, function (v) { st.tC = v; return v + " °C"; }).onchange = function () { runTracks(redraw); };
        var b = el("button", { type: "button", "class": "w-btn" }, "Run the sweep again"); b.onclick = function () { runSweep(redraw); }; body.append(b);
        body.append(el("p", { "class": "w-note" }, "Kr cannot be walked: boon-lay has no Kr coefficient in the buffer (todo!, gh:#541). Each atom is born evenly in the kernel; the particle sits at one temperature; nothing decays."));
        runTracks(redraw); runSweep(redraw);
      }
    });
    return frame;
  }

  // ─── 33: the pressure vessel ──────────────────────────────────────────
  function vessel(root) {
    var st = { hi: 2, tC: 1600 };
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var F = FD(), P = F.pressure, row = P.rows[st.hi], i = P.tC.indexOf(st.tC), g = F.geometry, wide = w >= 600, top = 52;
        var pmax = Math.ceil(Math.max.apply(null, row.p) / 1e7) * 10 / zoom, step = pmax > 60 ? 20 : pmax > 25 ? 10 : 5;
        var A = wide ? new Box(56, top, w * 0.58, h - 40, [1000, 2200], [0, pmax], false, false)
                     : new Box(56, top, w - 12, top + (h - top) * 0.55, [1000, 2200], [0, pmax], false, false);
        A.frame(ctx, "accident temperature (°C)", "pressure (MPa)", linTicks(1000, 2200, 300), linTicks(0, pmax, step));
        A.line(ctx, P.tC, row.p.map(function (v) { return v / 1e6; }), "#b85c38", 2);
        A.line(ctx, P.tC, row.pGas.map(function (v) { return v / 1e6; }), "#2f7fd8", 2, [5, 4]);
        A.line(ctx, P.tC, row.pCo.map(function (v) { return v / 1e6; }), "#555", 2, [2, 3]);
        legend(ctx, [["total", "#b85c38"], ["fission gas", "#2f7fd8", [5, 4]], ["CO", "#555", [2, 3]]], A.x0 + 4, A.y0 + 14, A.x1 - A.x0 - 8);
        ctx.strokeStyle = "#b85c38"; ctx.beginPath(); ctx.moveTo(A.X(st.tC), A.y0); ctx.lineTo(A.X(st.tC), A.y1); ctx.stroke();
        // The shell: a slice of the SiC with an arrow for the pressure and
        // the wall stress beside it.
        var p = row.p[i], sig = BP().stress(p, g.rMean, g.d0, 1);
        var cx = wide ? w * 0.79 : w / 2, cy = wide ? (top + h) / 2 : A.y1 + 30 + (h - A.y1 - 30) / 2, R = Math.min(wide ? w * 0.18 : w * 0.3, wide ? (h - top) * 0.35 : (h - A.y1 - 40) / 2);
        ctx.fillStyle = LAYER_COL.SiC; ctx.beginPath(); ctx.arc(cx, cy, R, 0, 2 * Math.PI); ctx.arc(cx, cy, R * g.ri / g.ra, 0, 2 * Math.PI, true); ctx.fill();
        ctx.fillStyle = LAYER_COL.buffer; ctx.beginPath(); ctx.arc(cx, cy, R * g.ri / g.ra * 0.97, 0, 2 * Math.PI); ctx.fill();
        var n = Math.min(14, Math.round(p / 3e6) + 2);
        for (var k = 0; k < n; k++) { var a = 2 * Math.PI * k / n; L.arrow(ctx, cx + 0.3 * R * Math.cos(a), cy + 0.3 * R * Math.sin(a), cx + 0.8 * R * Math.cos(a), cy + 0.8 * R * Math.sin(a), "#b85c38"); }
        ctx.fillStyle = css("--fg", "#1d2125"); ctx.font = "12px system-ui, sans-serif";
        var tx = wide ? cx - R : 8, ty = wide ? cy + R + 18 : cy - R - 6;
        ctx.fillText("p " + (p / 1e6).toFixed(1) + " MPa → σ " + (sig / 1e6).toFixed(0) + " MPa", tx, ty);
        return "After " + P.hours[st.hi] + " h at " + st.tC + " °C: " + (row.fd[i] * 100).toFixed(1) + " % of the stable fission gas has left the kernel, CO from " + row.opf[i].toPrecision(2) + " oxygen atoms per fission; p = " + (p / 1e6).toFixed(1) + " MPa, wall stress σ = r p / (2 d) = " + (sig / 1e6).toFixed(0) + " MPa. HTR-10 particle, an EXTRAPOLATION.";
      },
      panel: function (body, redraw) {
        L.buttons(body, "Hours into the accident", FD().pressure.hours.map(function (hh, k) { return [k, hh + " h"]; }), st.hi, function (v) { st.hi = v; redraw(); });
        L.slider(body, "Accident temperature (°C)", 1000, 2200, 100, st.tC, function (v) { st.tC = v; redraw(); return v + " °C"; });
        body.append(el("p", { "class": "w-note" }, "boon-lay fuel failure's AccidentHistory::pressure_at, irradiated at 776 °C (the report's HTR-Module average; not HTR-10's). Arrows: illustrative."));
      }
    });
    return frame;
  }

  // ─── 34: Weibull, weakest link ────────────────────────────────────────
  function weibullW(root) {
    var st = { gi: 0, sig: 178, mOver: null, seed: 34 };
    var frame = new L.Frame(root, {
      reset: function () { st.mOver = null; }, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var F = FD(), sv = F.strengthVsFluence, s0 = sv.s0[st.gi] / 1e6, m = st.mOver || sv.m[st.gi], wide = w >= 600, top = 52;
        var A = wide ? new Box(56, top, w * 0.55, h - 40, [0, 1200 / zoom], [-12, 0], false, true)
                     : new Box(56, top, w - 12, top + (h - top) * 0.55, [0, 1200 / zoom], [-12, 0], false, true);
        A.frame(ctx, "wall stress σ (MPa)", "fraction failed", linTicks(0, 1200 / zoom, 300 / Math.max(1, Math.round(zoom))), decTicks(-12, 0, 3));
        var xs = [], ys = [];
        for (var s = 1; s <= 1200; s += 4) { xs.push(s); ys.push(BP().weibull(s, s0, m)); }
        A.line(ctx, xs, ys, "#2a9d55", 2);
        ctx.strokeStyle = "#999"; ctx.setLineDash([3, 3]); ctx.beginPath(); ctx.moveTo(A.X(s0), A.y0); ctx.lineTo(A.X(s0), A.y1); ctx.stroke(); ctx.setLineDash([]);
        ctx.fillStyle = "#999"; ctx.font = "10px system-ui, sans-serif"; ctx.fillText("σ₀ (half fail)", A.X(s0) + 3, A.y0 + 12);
        var f = BP().weibull(st.sig, s0, m);
        ctx.fillStyle = "#b85c38"; ctx.beginPath(); ctx.arc(A.X(st.sig), A.Y(Math.max(f, 1e-12)), 4, 0, 2 * Math.PI); ctx.fill();
        // A population of 400 particles, each with a strength drawn from the
        // same Weibull law: those weaker than sigma are drawn broken.
        var r = BP().rng(st.seed), n = 400, cols = 20, bx = wide ? w * 0.6 : 20, by = wide ? top + 10 : A.y1 + 34, bw = wide ? w * 0.38 : w - 40, bh = wide ? h - top - 50 : h - by - 12;
        var cs = Math.min(bw / cols, bh / (n / cols)), broken = 0;
        for (var k = 0; k < n; k++) {
          var str = s0 * Math.pow(-Math.log(1 - r()) / Math.LN2, 1 / m), x = bx + (k % cols) * cs + cs / 2, y = by + Math.floor(k / cols) * cs + cs / 2;
          var bad = str < st.sig; if (bad) broken++;
          ctx.fillStyle = bad ? "#c0392b" : "#2a9d55"; ctx.beginPath(); ctx.arc(x, y, cs * 0.38, 0, 2 * Math.PI); ctx.fill();
        }
        return "σ₀ = " + s0.toFixed(0) + " MPa and m = " + m.toFixed(2) + (st.mOver ? " (your m)" : " after a fast fluence of " + sv.gamma[st.gi] + "×10²⁵ m⁻²") + ". At σ = " + st.sig + " MPa the law gives " + sci(f) + " failed; in this drawing of 400 particles, " + broken + " broke.";
      },
      panel: function (body, redraw) {
        var sv = FD().strengthVsFluence;
        L.slider(body, "Fast fluence (10²⁵ m⁻²)", 0, sv.gamma.length - 1, 1, 0, function (v) { st.gi = v; redraw(); return String(sv.gamma[v]); });
        L.slider(body, "Wall stress σ (MPa)", 20, 1200, 2, st.sig, function (v) { st.sig = v; redraw(); return v + " MPa"; });
        L.slider(body, "Try your own m (0 = the code's)", 0, 20, 0.5, 0, function (v) { st.mOver = v > 0 ? v : null; redraw(); return v > 0 ? String(v) : "code"; });
        var b = el("button", { type: "button", "class": "w-btn" }, "Draw new particles"); b.onclick = function () { st.seed++; redraw(); }; body.append(b);
        body.append(el("p", { "class": "w-note" }, "Strength before irradiation 834 MPa, m 8.02: a STAND-IN (the report's HTR-Module SiC), not HTR-10 data. Irradiated at 776 °C. The 400 dots are a picture of the fraction, not a simulation."));
      }
    });
    return frame;
  }

  // ─── 35: the wall gets thinner ────────────────────────────────────────
  function thinning(root) {
    var st = { mode: "corrosion", ti: 1, hi: 8 };
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var F = FD(), T = F.thinning, wide = w >= 600, top = 52, s;
        var A = wide ? new Box(60, top, w * 0.6, h - 40, [0, 500], [0, 1], false, false) : new Box(60, top, w - 12, top + (h - top) * 0.6, [0, 500], [0, 1], false, false);
        if (st.mode === "corrosion") {
          A.yr = [1, 1 + 0.3 / zoom];
          A.frame(ctx, "hours", "thinning factor FKOR", linTicks(0, 500, 100), linTicks(1, 1 + 0.3 / zoom, 0.05 / Math.max(1, Math.round(zoom)), function (v) { return v.toFixed(2); }));
          T.rows.forEach(function (row, k) { A.line(ctx, T.hours, row.fkor, ["#2f7fd8", "#2a9d55", "#d4a017", "#b85c38", "#c0392b"][k], k === st.ti ? 3 : 1.5); });
          legend(ctx, T.rows.map(function (row, k) { return [row.tC + " °C", ["#2f7fd8", "#2a9d55", "#d4a017", "#b85c38", "#c0392b"][k]]; }), A.x0 + 4, A.y0 + 14, A.x1 - A.x0 - 8);
          var fk = T.rows[st.ti].fkor[st.hi];
          s = "Corrosion (Eq (7)): after " + T.hours[st.hi] + " h at " + T.rows[st.ti].tC + " °C the wall is " + (F.geometry.d0 * 1e6 / fk).toFixed(2) + " µm of " + (F.geometry.d0 * 1e6).toFixed(0) + " (FKOR " + fk.toFixed(4) + "), so the stress is " + ((fk - 1) * 100).toFixed(2) + " % higher.";
          // The wall itself.
          var bx = wide ? w * 0.68 : 60, by = wide ? top + 20 : A.y1 + 40, bw = wide ? w * 0.28 : w - 80, bh = wide ? h - top - 70 : h - by - 20;
          ctx.fillStyle = "#ddd"; ctx.fillRect(bx, by, bw, bh);
          ctx.fillStyle = LAYER_COL.SiC; ctx.fillRect(bx, by, bw / fk, bh);
          ctx.fillStyle = css("--fg", "#1d2125"); ctx.font = "10px system-ui, sans-serif"; ctx.fillText("SiC left (grey: eaten)", bx, by - 4);
        } else if (st.mode === "decomposition") {
          var Dd = F.decomposition; A.xr = [1600, 2400]; A.yr = [-16, 0]; A.logy = true;
          A.frame(ctx, "temperature (°C), 200 h hold", "φ₂ (failed by decomposition)", linTicks(1600, 2400, 200), decTicks(-16, 0, 4));
          A.line(ctx, Dd.tC, Dd.sphere200, "#b85c38", 2); A.line(ctx, Dd.tC, Dd.loose200, "#555", 2, [5, 4]);
          legend(ctx, [["particles in a sphere (14b, default)", "#b85c38"], ["loose particles (14a)", "#555", [5, 4]]], A.x0 + 4, A.y0 + 14, A.x1 - A.x0 - 8);
          ctx.fillStyle = "#c0392b"; ctx.font = "bold 12px system-ui, sans-serif"; ctx.fillText("UNVERIFIED: no output of the report checks Eqs (11)-(14b)", A.x0 + 4, A.y1 + 40 > h - 4 ? A.y1 - 8 : A.y1 + 40);
          s = "SiC decomposition (Eqs (11)-(14b)): the layer turns to Si vapour and graphite and stops holding pressure. Rate constant k = (375/d₀) exp(−556000/RT); the code's own docs say nothing here is checked against a figure or table of the report.";
        } else {
          var G = F.grainBoundary; A.xr = [1000, 2600]; A.yr = [0, F.grainBoundary.m0 * 1.1];
          A.frame(ctx, "temperature (°C), 200 h", "Weibull modulus m", linTicks(1000, 2600, 400), linTicks(0, G.m0 * 1.1, 2));
          A.line(ctx, G.tC, G.m200, "#7a4cc2", 2);
          ctx.strokeStyle = "#999"; ctx.setLineDash([3, 3]); ctx.beginPath(); ctx.moveTo(A.x0, A.Y(G.m0)); ctx.lineTo(A.x1, A.Y(G.m0)); ctx.stroke(); ctx.setLineDash([]);
          s = "Grain-boundary attack (Eqs (10b), (10c)), OFF by default as in the report: it lowers the Weibull modulus m (more scatter in strength) from " + G.m0.toFixed(2) + " towards 44 % of it. Switch it on in lesson 36 to see what it does to failure.";
        }
        return s;
      },
      panel: function (body, redraw) {
        L.buttons(body, "Which thinning", [["corrosion", "Corrosion"], ["decomposition", "Decomposition"], ["gb", "Grain-boundary attack"]], st.mode, function (v) { st.mode = v; redraw(); });
        L.slider(body, "Corrosion: temperature", 0, FD().thinning.rows.length - 1, 1, st.ti, function (v) { st.ti = v; redraw(); return FD().thinning.rows[v].tC + " °C"; });
        L.slider(body, "Corrosion: hours", 0, FD().thinning.hours.length - 1, 1, st.hi, function (v) { st.hi = v; redraw(); return FD().thinning.hours[v] + " h"; });
        body.append(el("p", { "class": "w-note" }, "Corrosion uses the pre-factor 5.87e-8 m/s that reproduces the report's own Fig. 4; the printed 5.87e-7 does not (boon-lay's corrosion.rs docs)."));
      }
    });
    return frame;
  }

  // ─── 36 and 37: an accident, and the release ──────────────────────────
  function historyOptions() {
    var F = FD(), o = [];
    F.ramps.forEach(function (r, k) { o.push(["r" + k, "heat-up to " + r.peak + " °C"]); });
    F.holds.forEach(function (hd, k) { if (!hd.gb) o.push(["h" + k, hd.tC + " °C hold"]); });
    return o;
  }
  function getHistory(key, gb) {
    var F = FD();
    if (key[0] === "r") return F.ramps[+key.slice(1)];
    var base = F.holds[+key.slice(1)];
    if (!gb) return base;
    return F.holds.filter(function (hd) { return hd.tC === base.tC && hd.gb; })[0];
  }
  function col(rows, name) { var j = FD().rowFields.indexOf(name); return rows.map(function (r) { return r[j]; }); }
  function accident(root) {
    var st = { key: "r1", gb: false, phiO: false, t: 1, playing: false };
    var frame = new L.Frame(root, {
      reset: function () { st.t = 1; },
      tick: function (dt) { if (!st.playing) return false; st.t = Math.min(1, st.t + dt * 0.12); if (st.t >= 1) st.playing = false; return st.playing; },
      draw: function (ctx, w, h, zoom) {
        var F = FD(), H = getHistory(st.key, st.gb), rows = H.rows, hrs = col(rows, "hours"), tmax = hrs[hrs.length - 1], top = 52;
        var n = Math.max(1, Math.round(st.t * (rows.length - 1))), cut = function (a) { return a.slice(0, n + 1); };
        var T = new Box(60, top, w - 12, top + (h - top) * 0.28, [0, tmax], [600, 2300], false, false);
        T.frame(ctx, "", "T (°C)", [], linTicks(800, 2200, 700));
        T.line(ctx, hrs, col(rows, "tC"), "#ccc", 2); T.line(ctx, cut(hrs), cut(col(rows, "tC")), "#b85c38", 2);
        var lo = -14 + Math.round((zoom - 1) * 4);
        var A = new Box(60, T.y1 + 20, w - 12, h - 30, [0, tmax], [Math.min(lo, -1), 0], false, true);
        A.frame(ctx, "hours", "fraction failed", linTicks(0, tmax, 100), decTicks(A.yr[0], 0, 2));
        var po = st.phiO ? F.asManufacturedTarget : 0, p1 = col(rows, "phi1"), p2 = col(rows, "phi2");
        var tot = p1.map(function (v, k) { return BP().total(po, v, p2[k]); });
        A.line(ctx, cut(hrs), cut(p1), "#2f7fd8", 2); A.line(ctx, cut(hrs), cut(p2), "#7a4cc2", 2, [5, 4]); A.line(ctx, cut(hrs), cut(tot), "#111", 2.5);
        if (po) { ctx.strokeStyle = "#999"; ctx.setLineDash([2, 3]); ctx.beginPath(); ctx.moveTo(A.x0, A.Y(po)); ctx.lineTo(A.x1, A.Y(po)); ctx.stroke(); ctx.setLineDash([]); }
        legend(ctx, [["φ₁ pressure vessel", "#2f7fd8"], ["φ₂ decomposition", "#7a4cc2", [5, 4]], ["total", "#111"]], A.x0 + 4, A.y0 + 14, A.x1 - A.x0 - 8);
        ctx.fillStyle = "#c0392b"; ctx.font = "bold 11px system-ui, sans-serif"; ctx.fillText("HTR-10: an EXTRAPOLATION", T.x0 + 4, T.y0 + 13);
        var r = rows[n], f = F.rowFields;
        return "At " + r[0].toFixed(0) + " h, " + r[1].toFixed(0) + " °C: p " + (r[f.indexOf("p")] / 1e6).toFixed(1) + " MPa, σ " + (r[f.indexOf("sigma")] / 1e6).toFixed(0) + " MPa, FKOR " + r[f.indexOf("fkor")].toFixed(4) + "; φ₁ " + sci(r[f.indexOf("phi1")]) + ", φ₂ " + sci(r[f.indexOf("phi2")]) + ", total " + sci(tot[n]) + (st.gb ? " (grain-boundary attack ON)" : "") + ".";
      },
      panel: function (body, redraw, play) {
        L.buttons(body, "History", historyOptions(), st.key, function (v) { st.key = v; st.t = 1; redraw(); });
        L.toggle(body, "Grain-boundary attack (holds only; off by default)", st.gb, function (v) { st.gb = v; if (st.key[0] === "r" && v) st.key = "h4"; redraw(); });
        L.toggle(body, "Add as-manufactured defects φ₀ = 6e-5 (an input)", st.phiO, function (v) { st.phiO = v; redraw(); });
        var b = el("button", { type: "button", "class": "w-btn" }, "▶ Play the accident"); b.onclick = function () { st.t = 0; st.playing = true; play(); }; body.append(b);
        body.append(el("p", { "class": "w-note" }, "The heat-ups are ILLUSTRATIVE prescribed histories (50 h up, 50 h at peak, 200 h down), not a plant calculation. Irradiated at 776 °C; strength and fluence are stand-ins (lesson 34)."));
      }
    });
    return frame;
  }
  function release(root) {
    var st = { key: "h2", el: "Cs" };
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var F = FD(), H = getHistory(st.key, false), rows = H.rows, hrs = col(rows, "hours"), tmax = hrs[hrs.length - 1], top = 52;
        var rf = H.release[st.el], tot = col(rows, "total"), rel = tot.map(function (v, k) { return v * rf[k]; });
        var lo = -14 + Math.round((zoom - 1) * 4);
        var A = new Box(60, top, w - 12, h - 30, [0, tmax], [Math.min(lo, -1), 0], false, true);
        A.frame(ctx, "hours", "fraction", linTicks(0, tmax, 100), decTicks(A.yr[0], 0, 2));
        A.line(ctx, hrs, rf, EL_COL[st.el], 2, [5, 4]); A.line(ctx, hrs, tot, "#111", 1.5, [2, 3]); A.line(ctx, hrs, rel, "#b85c38", 2.5);
        legend(ctx, [["kernel release by Booth, " + st.el, EL_COL[st.el], [5, 4]], ["particles failed φ", "#111", [2, 3]], ["released share of all " + st.el, "#b85c38"]], A.x0 + 4, A.y0 + 14, A.x1 - A.x0 - 8);
        var k = rows.length - 1;
        return "After " + hrs[k].toFixed(0) + " h: " + (100 * rf[k]).toPrecision(3) + " % of the " + st.el + " has left each kernel (Booth), " + sci(tot[k]) + " of the particles have failed, so " + sci(rel[k]) + " of all the " + st.el + " is out. Intact particles are counted as holding everything.";
      },
      panel: function (body, redraw) {
        L.buttons(body, "History", historyOptions(), st.key, function (v) { st.key = v; redraw(); });
        L.buttons(body, "Element", [["Cs", "Cs"], ["Sr", "Sr"], ["Kr", "Kr"]], st.el, function (v) { st.el = v; redraw(); });
        body.append(el("p", { "class": "w-note" }, "Booth: TRISO-ATOPS's booth_transient on the time integral of D/a², a = the 250 µm kernel. Failed fraction: boon-lay fuel failure (lesson 36)."));
      }
    });
    return frame;
  }

  // ─── 38: what the model leaves out ────────────────────────────────────
  function leaves(root) {
    var st = { pick: -1 };
    var ITEMS = [
      ["in", "Gas pressure, ideal gas", "p = nRT/V_f with fission gas and CO (lesson 33)."],
      ["in", "Thin-shell SiC stress", "σ = r p/(2d) (lesson 33). Thin shell only: no thick-wall solution."],
      ["in", "Weibull strength, irradiated", "Eqs (1), (8a)-(9b) (lesson 34). HTR-10's strength and fluence are stand-ins."],
      ["in", "SiC corrosion", "Eq (7) with the figure-consistent pre-factor (lesson 35)."],
      ["simplified", "SiC decomposition", "Eqs (11)-(14b): implemented but UNVERIFIED against any output of the report."],
      ["simplified", "Grain-boundary attack", "Eqs (10b), (10c): implemented, OFF by default (as in the report)."],
      ["simplified", "As-manufactured defects φ₀", "An input; the 6e-5 target is a named constant, never a default."],
      ["simplified", "Range of the model", "Built for German TRISO over 1600-2500 °C; HTR-10 is an extrapolation; not for normal-operation failure."],
      ["out", "Oxidation failure in air or steam", "Mechanistic SiC and kernel attack: gh:#441, #443, #444."],
      ["out", "Pd and lanthanide attack on SiC", "Not modelled anywhere in the workspace (theory book step 4 names the sources)."],
      ["out", "Amoeba effect (kernel migration)", "Not modelled anywhere in the workspace; source pending."],
      ["out", "PyC creep, swelling, cracking, debonding", "No such laws in the chain (theory book step 6)."],
      ["out", "Real-gas pressure", "Ideal gas only; the error is not estimated (theory book step 6)."],
      ["out", "Validation", "Nothing here is compared with measured failure or release data."]
    ];
    var COL = { "in": "#2a9d55", simplified: "#d4a017", out: "#999" };
    var frame = new L.Frame(root, {
      reset: function () { st.pick = -1; }, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var top = 52, cols = w >= 600 ? 2 : 1, cw = (w - 16) / cols, rh = Math.min(26, (h - top - 10) / Math.ceil(ITEMS.length / cols)) * Math.min(zoom, 1.3);
        ITEMS.forEach(function (it, k) {
          var x = 8 + (k % cols) * cw, y = top + Math.floor(k / cols) * rh;
          ctx.strokeStyle = COL[it[0]]; ctx.lineWidth = 2; ctx.setLineDash(it[0] === "out" ? [4, 3] : []);
          ctx.fillStyle = k === st.pick ? "#f3e6dc" : css("--panel", "#fff");
          ctx.fillRect(x, y, cw - 8, rh - 4); ctx.strokeRect(x, y, cw - 8, rh - 4); ctx.setLineDash([]);
          ctx.fillStyle = css("--fg", "#1d2125"); ctx.font = "12px system-ui, sans-serif";
          ctx.fillText((it[0] === "in" ? "✓ " : it[0] === "out" ? "✗ " : "~ ") + it[1], x + 6, y + rh / 2 + 2);
        });
        return st.pick >= 0 ? ITEMS[st.pick][1] + ": " + ITEMS[st.pick][2] : "Green ✓: in the model. Amber ~: in, but simplified or unverified. Grey ✗, dashed: not modelled. Pick one in the panel.";
      },
      panel: function (body, redraw) {
        L.buttons(body, "Explain", ITEMS.map(function (it, k) { return [k, it[1]]; }), -1, function (v) { st.pick = v; redraw(); });
      }
    });
    return frame;
  }

  // Numbers in the prose, bound by data-bd="...".
  function fillBd() {
    var B = BD(), F = FD(), th = B.thickness, um = function (x) { return (x * 1e6).toFixed(0) + " µm"; };
    var h200 = function (tC) { var H = F.holds.filter(function (x) { return x.tC === tC && !x.gb; })[0], j = H.rows.findIndex(function (r) { return r[0] === 200; }); return H.rows[j]; };
    var f = F.rowFields, r16 = h200(1600), r22 = h200(2200), r20 = h200(2000), r12 = h200(1200);
    var gbOff = F.holds.filter(function (x) { return x.tC === 1600 && !x.gb; })[0], gbOn = F.holds.filter(function (x) { return x.tC === 1600 && x.gb; })[0];
    var p0 = F.pressure.rows[2], i16 = F.pressure.tC.indexOf(1600);
    var ex = function (elm, tC) { return B.wos.exact.filter(function (x) { return x.el === elm && x.tC === tC; })[0]; };
    var pr = function (elm) { return B.wos.probes.filter(function (x) { return x.el === elm; })[0]; };
    var sicCs = wD("Cs", "SiC", 1200), pycCs = wD("Cs", "PyC", 1200);
    var map = {
      kernelR: um(th.kernel), bufferT: um(th.buffer), ipycT: um(th.IPyC), sicT: um(th.SiC), opycT: um(th.OPyC),
      csContrast1200: (pycCs / sicCs).toFixed(0),
      csSic1200: fmtT(th.SiC * th.SiC / sicCs), csIpyc1200: fmtT(th.IPyC * th.IPyC / pycCs),
      krIpyc1000: fmtT(th.IPyC * th.IPyC / wD("Kr", "PyC", 1000)),
      srKernel1600: fmtT(th.kernel * th.kernel / wD("Sr", "kernel", 1600)), srSic1600: fmtT(th.SiC * th.SiC / wD("Sr", "SiC", 1600)),
      residence: fmtT(F.strength.residenceDays * 86400),
      exCs1600: fmtT(ex("Cs", 1600).mean), exAg1600: fmtT(ex("Ag", 1600).mean), exSr1600: fmtT(ex("Sr", 1600).mean), exSr1000: fmtT(ex("Sr", 1000).mean),
      exCsSicShare: (100 * ex("Cs", 1600).terms[3] / ex("Cs", 1600).mean).toFixed(0) + " %", exSrKernelShare: (100 * ex("Sr", 1600).terms[0] / ex("Sr", 1600).mean).toFixed(0) + " %",
      probeSteps: B.wos.probeSteps.toExponential(0).replace("e+", "×10^"), probeCsSec: pr("Cs").seconds.toFixed(1) + " s",
      probeCsBuffer: (100 * pr("Cs").perLayer[1] / pr("Cs").perLayer.reduce(function (a, b) { return a + b; }, 0)).toFixed(2) + " %",
      probeCsEntries: String(pr("Cs").ipycEntries), probeCsRmax: (pr("Cs").rMax * 1e6).toFixed(1) + " µm",
      p1600: (p0.p[i16] / 1e6).toFixed(1) + " MPa", pGas1600: (100 * p0.pGas[i16] / p0.p[i16]).toFixed(0) + " %",
      sigma1600: (r16[f.indexOf("sigma")] / 1e6).toFixed(0) + " MPa", s0: (F.strength.s0 / 1e6).toFixed(0) + " MPa", m0: F.strength.m.toFixed(2),
      phi1_1200: sci(r12[f.indexOf("phi1")]), phi1_1600: sci(r16[f.indexOf("phi1")]), phi1_2000: sci(r20[f.indexOf("phi1")]), phi2_2000: sci(r20[f.indexOf("phi2")]),
      phi1_2200: sci(r22[f.indexOf("phi1")]), phi2_2200: sci(r22[f.indexOf("phi2")]),
      gbRatio: (gbOn.rows[gbOn.rows.length - 1][f.indexOf("phi1")] / gbOff.rows[gbOff.rows.length - 1][f.indexOf("phi1")]).toPrecision(3),
      phi1Start: sci(F.phi1Start), fkor1600: r16[f.indexOf("fkor")].toFixed(4),
      csRelease1600: (100 * gbOff.release.Cs[gbOff.rows.findIndex(function (r) { return r[0] === 200; })]).toPrecision(3) + " %",
      srRelease1600: (100 * gbOff.release.Sr[gbOff.rows.findIndex(function (r) { return r[0] === 200; })]).toPrecision(3) + " %"
    };
    document.querySelectorAll("[data-bd]").forEach(function (n) { var k = n.getAttribute("data-bd"); if (k in map) n.textContent = map[k]; });
  }
  L.widget("bd-numbers", fillBd);
  L.widget("particle", particle);
  L.widget("dlayers", dlayers);
  L.widget("matrix", matrix);
  L.widget("whole", whole);
  L.widget("vessel", vessel);
  L.widget("weibull", weibullW);
  L.widget("thinning", thinning);
  L.widget("accident", accident);
  L.widget("release", release);
  L.widget("leaves", leaves);
})();
